class LFUCache {
public:
  explicit LFUCache(int capacity);
  int get(int key);
  void put(int key, int value);
};

questions.modelAnswer:
#include <list>
#include <unordered_map>

class LFUCache {
  struct Node { int key, val, freq; };
  int cap_, minFreq_ = 0;
  std::unordered_map<int, std::list<Node>> byFreq_;            // freq -> nodes, front = most recent
  std::unordered_map<int, std::list<Node>::iterator> idx_;     // key -> node

  void touch(std::list<Node>::iterator it) {                   // freq++ and move to the next bucket
    int f = it->freq;
    auto& from = byFreq_[f];
    auto& to = byFreq_[f + 1];
    to.splice(to.begin(), from, it);                           // the iterator stays valid
    it->freq = f + 1;
    if (from.empty()) {
      byFreq_.erase(f);
      if (minFreq_ == f) minFreq_ = f + 1;
    }
  }
public:
  explicit LFUCache(int capacity) : cap_(capacity) {}

  int get(int key) {
    auto it = idx_.find(key);
    if (it == idx_.end()) return -1;
    touch(it->second);
    return it->second->val;
  }

  void put(int key, int value) {
    if (cap_ <= 0) return;
    if (auto it = idx_.find(key); it != idx_.end()) {
      it->second->val = value;
      touch(it->second);
      return;
    }
    if ((int)idx_.size() == cap_) {                            // evict: lowest freq, then least recent
      auto& bucket = byFreq_[minFreq_];
      idx_.erase(bucket.back().key);
      bucket.pop_back();
      if (bucket.empty()) byFreq_.erase(minFreq_);
    }
    auto& b1 = byFreq_[1];
    b1.push_front({key, value, 1});
    idx_[key] = b1.begin();
    minFreq_ = 1;                                              // a new key always has freq 1
  }
};

