class MyCircularQueue {
public:
  explicit MyCircularQueue(int k);
  bool enQueue(int value);
  bool deQueue();
  int Front() const;
  int Rear() const;
  bool isEmpty() const;
  bool isFull() const;
};

questions.modelAnswer:
#include <vector>

class MyCircularQueue {
  std::vector<int> buf_;
  int head_ = 0, count_ = 0;          // count_ tells "full" apart from "empty"
public:
  explicit MyCircularQueue(int k) : buf_(k) {}
  bool enQueue(int v) {
    if (isFull()) return false;
    buf_[(head_ + count_) % buf_.size()] = v;
    ++count_;
    return true;
  }
  bool deQueue() {
    if (isEmpty()) return false;
    head_ = (head_ + 1) % buf_.size();
    --count_;
    return true;
  }
  int Front() const { return isEmpty() ? -1 : buf_[head_]; }
  int Rear() const { return isEmpty() ? -1 : buf_[(head_ + count_ - 1) % buf_.size()]; }
  bool isEmpty() const { return count_ == 0; }
  bool isFull() const { return count_ == (int)buf_.size(); }
};

