class TimeMap {
public:
  void set(const std::string& key, const std::string& value, int timestamp);
  std::string get(const std::string& key, int timestamp) const;
};

questions.modelAnswer:
#include <iterator>
#include <map>
#include <string>
#include <unordered_map>

class TimeMap {
  // key -> (timestamp -> value), each inner map sorted by timestamp
  std::unordered_map<std::string, std::map<int, std::string>> data_;
public:
  void set(const std::string& key, const std::string& value, int timestamp) {
    data_[key][timestamp] = value;
  }
  std::string get(const std::string& key, int timestamp) const {
    auto it = data_.find(key);
    if (it == data_.end()) return "";
    const auto& versions = it->second;
    auto v = versions.upper_bound(timestamp);   // first version strictly after timestamp
    if (v == versions.begin()) return "";       // every version is newer than the query
    return std::prev(v)->second;                // the latest version <= timestamp
  }
};

