class Allocator {
public:
  explicit Allocator(int n);
  int allocate(int size, int mID);
  int freeMemory(int mID);
};

questions.modelAnswer:
#include <iterator>
#include <map>
#include <unordered_map>
#include <vector>

class Allocator {
  std::map<int, int> free_;                                   // start -> length, disjoint and merged
  std::unordered_map<int, std::vector<std::pair<int, int>>> owned_;   // mID -> blocks (start, len)
public:
  explicit Allocator(int n) { free_[0] = n; }

  int allocate(int size, int mID) {
    for (auto it = free_.begin(); it != free_.end(); ++it) {  // first fit = leftmost block that fits
      auto [start, len] = *it;
      if (len < size) continue;
      free_.erase(it);
      if (len > size) free_[start + size] = len - size;       // keep the leftover tail
      owned_[mID].push_back({start, size});
      return start;
    }
    return -1;
  }

  int freeMemory(int mID) {
    auto o = owned_.find(mID);
    if (o == owned_.end()) return 0;
    int total = 0;
    for (auto [start, len] : o->second) {
      total += len;
      auto it = free_.emplace(start, len).first;
      if (auto nx = std::next(it); nx != free_.end() && start + len == nx->first) {
        it->second += nx->second;                              // merge with the right neighbour
        free_.erase(nx);
      }
      if (it != free_.begin()) {
        auto pv = std::prev(it);
        if (pv->first + pv->second == it->first) {             // merge with the left neighbour
          pv->second += it->second;
          free_.erase(it);
        }
      }
    }
    owned_.erase(o);
    return total;
  }
};

