class TicTacToe {
public:
  explicit TicTacToe(int n);
  int move(int row, int col, int player);
};

questions.modelAnswer:
#include <cstdlib>
#include <vector>

class TicTacToe {
  int n_;
  std::vector<int> rows_, cols_;   // player 1 adds +1, player 2 adds -1
  int diag_ = 0, anti_ = 0;
public:
  explicit TicTacToe(int n) : n_(n), rows_(n), cols_(n) {}

  // Returns 0 if nobody has won yet, otherwise the winner (1 or 2). O(1) per move.
  int move(int row, int col, int player) {
    int d = (player == 1) ? 1 : -1;
    rows_[row] += d;
    cols_[col] += d;
    if (row == col) diag_ += d;
    if (row + col == n_ - 1) anti_ += d;
    if (std::abs(rows_[row]) == n_ || std::abs(cols_[col]) == n_ ||
        std::abs(diag_) == n_ || std::abs(anti_) == n_)
      return player;
    return 0;
  }
};
